import React,{useState,useMemo} from 'react';
import {createRoot} from 'react-dom/client';
import {ComputerDevices,ComputerDevicesProvider} from '../../../core-ui/src/ComputerDevices';
import {computerResponse,allowedComputer} from '../../../core-ui/src/computer-contract.js';
import '../../../core-ui/src/styles.css';
import '../../../core-ui/src/phone.css';
function Fixture(){const [side,setSide]=useState('first'),[theme,setTheme]=useState('light'),[approval,setApproval]=useState<any>(null),[notice,setNotice]=useState('');const request=async(method:string,path:string,body?:any)=>{const r=await fetch('/'+side+path,{method,headers:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});return {status:r.status,body:await r.json()};};const client=useMemo(()=>({request:async(r:any)=>{if(!allowedComputer(r.method,r.path,r.body))throw Error('UI boundary refused request');const response=await request(r.method,r.path,r.body);return {...response,body:computerResponse(r.path,response.status,response.body)};}}),[side]);const review=async()=>{const r=await request('GET','/api/approvals?status=pending');const item=r.body.approvals[0];if(item)setApproval((await request('GET','/api/approvals/'+item.id)).body.approval);};return <div className="shell" data-theme={theme} style={{display:'block',width:'100vw',height:'100vh',padding:20,overflow:'auto'}}><nav style={{display:'flex',gap:8,flexWrap:'wrap',marginBottom:20}}>{['first','second','third'].map((s,i)=><button key={s} onClick={()=>{setSide(s);setApproval(null);}}>{['First computer','Second computer','Third computer'][i]}</button>)}<button onClick={()=>setTheme(t=>t==='light'?'dark':'light')}>Change theme</button></nav><ComputerDevicesProvider key={side} client={client as any} enabled><ComputerDevices client={client as any} onApprovals={()=>void review()}/></ComputerDevicesProvider>{approval&&<section aria-label="Actual owner approval"><h3>Exact local owner approval</h3><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{JSON.stringify(approval.params,null,2)}</pre><button onClick={async()=>{const r=await request('POST','/api/approvals/'+approval.id+'/approve',{paramsHash:approval.paramsHash});setNotice(r.status===200?'Owner approval submitted.':'Approval refused.');setApproval(null);}}>Approve exact change</button></section>}<p role="status">{notice}</p></div>;}createRoot(document.getElementById('root')!).render(<Fixture/>);
